import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.UpdateBlockSynced{Position: protocol.BlockPos{1, -2, 3}, NewBlockRuntimeID: 300, Flags: 3, Layer: 1,
# EntityUniqueID: 4294967297, TransitionType: packet.EntityToBlockTransition}
DESTROY = bytes.fromhex("020306ac020301818080801002")

# generated by gophertunnel b8bd735:
# packet.UpdateBlockSynced{Position: protocol.BlockPos{0, 0, 0}, NewBlockRuntimeID: 0, Flags: 200, Layer: 0,
# EntityUniqueID: 64, TransitionType: 0}
NONE = bytes.fromhex("00000000c801004000")

GOLDENS = [
    pytest.param(
        v2225.UpdateBlockSyncedPacket(
            pos=v2225.BlockPos(x=1, y=-2, z=3),
            runtime_id=300,
            update_flags=3,
            layer=1,
            entity_unique_id=4294967297,
            message=v2225.ActorBlockSyncMessage.MessageId.DESTROY,
        ),
        DESTROY,
        id="destroy",
    ),
    pytest.param(
        v2225.UpdateBlockSyncedPacket(
            update_flags=200,
            entity_unique_id=64,
            message=v2225.ActorBlockSyncMessage.MessageId.NONE,
        ),
        NONE,
        id="none",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_update_block_synced_is_packet_110(version):
    assert version.PACKETS[110] is version.UpdateBlockSyncedPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_block_synced_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_block_synced_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
